package com.tokyoghoul.rpg.network;

import com.tokyoghoul.rpg.TokyoGhoulRPG;
import com.tokyoghoul.rpg.capability.GhoulData; import com.tokyoghoul.rpg.v2.KaguneType; import net.minecraft.network.FriendlyByteBuf; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.phys.AABB; import net.minecraft.world.phys.Vec3; import net.minecraft.world.level.ClipContext; import net.minecraft.core.particles.ParticleTypes; import net.minecraft.sounds.SoundEvents; import net.minecraftforge.network.NetworkEvent; import java.util.function.Supplier;
public record KaguneAttackPacket(int action){
 public static void encode(KaguneAttackPacket p,FriendlyByteBuf b){b.writeInt(p.action);} public static KaguneAttackPacket decode(FriendlyByteBuf b){return new KaguneAttackPacket(b.readInt());}
 public static void handle(KaguneAttackPacket p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->{var player=c.get().getSender();if(player==null)return;GhoulData.get(player).ifPresent(d->{if((d.getRace()!=GhoulData.Race.GHOUL&&d.getRace()!=GhoulData.Race.HALF_GHOUL)||!d.isKaguneActive())return; long now=player.level().getGameTime(); if(now<player.getPersistentData().getLong("TG_KaguneAttackCooldown"))return; player.getPersistentData().putLong("TG_KaguneAttackCooldown",now+8L);KaguneType type=d.getKaguneType();double range=type==KaguneType.SHOOTING?20D:type==KaguneType.LONG?14D:4.8D;Vec3 from=player.getEyePosition(),look=player.getLookAngle(),to=from.add(look.scale(range));var clip=player.level().clip(new ClipContext(from,to,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,player));double max=clip.getType()==net.minecraft.world.phys.HitResult.Type.BLOCK?from.distanceTo(clip.getLocation()):range;AABB box=player.getBoundingBox().expandTowards(look.scale(max)).inflate(type==KaguneType.LONG?1.1:.65);LivingEntity best=null;double bd=Double.MAX_VALUE;for(LivingEntity e:player.level().getEntitiesOfClass(LivingEntity.class,box,x->x!=player&&x.isAlive())){Vec3 delta=e.getBoundingBox().getCenter().subtract(from);double along=delta.dot(look);if(along<0||along>max)continue;double side=delta.subtract(look.scale(along)).length();if(side>e.getBbWidth()+.75)continue;if(along<bd){best=e;bd=along;}}if(best!=null){float base=type==KaguneType.SHOOTING?7f+d.getKagune()*1.1f:type==KaguneType.LONG?8f+d.getKagune()*1.25f:4.5f+d.getKagune();float dmg=p.action()>0?base*1.35f:base;best.hurt(player.damageSources().playerAttack(player),dmg);if(type==KaguneType.SHOOTING)best.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN,25,0));if(type==KaguneType.LONG)best.knockback(p.action()>0?1.0D:.8D,player.getX()-best.getX(),player.getZ()-best.getZ());if(player.level() instanceof ServerLevel sl){sl.sendParticles(ParticleTypes.CRIT,best.getX(),best.getY()+best.getBbHeight()*.55,best.getZ(),p.action()>0?18:10,.2,.2,.2,.08);sl.playSound(null,player.blockPosition(),TokyoGhoulRPG.KAGUNE_HIT.get(),player.getSoundSource(),.82f,p.action()>0?.55f:.8f);}}});});c.get().setPacketHandled(true);}
}
